  /// (`owner/repo`) is provided, avoiding false positives on non-GitHub text.
  static List<String> extractGithubIssueKeys(
    String? text, {
    String? defaultRepo,
  }) {
    if (text == null || text.isEmpty) return const [];
    final repo = (defaultRepo != null && defaultRepo.contains('/'))
        ? defaultRepo.trim()
